G=load()

# hypothesis: find noise cells (not background/lattice); their rows/cols form grid; output cell = parity of its 4 corners
def solve(g):
    h,w=len(g),len(g[0]); cnt=Counter(v for r in g for v in r)
    bg=cnt.most_common(1)[0][0]
    # lines: full rows or cols of color != bg -> lattice color L (most common after bg)
    lset=set(v for v,c in cnt.items() if c>=cnt[bg] and v!=bg); L=max(lset,key=lambda v:(v,c)) if len(lset)>1 else min(lset)
    lr=[i for i in range(h) if len(set(g[i]))==1 and g[i][0]!=bg]
    lc=[c for c in range(w) if len({g[r][c] for r in range(h)})==1 and g[0][c]!=bg]
    noise=[(r,c,g[r][c]) for r in range(h) for c in range(w) if g[r][c] not in (bg,L)]
    rr=sorted(set(r for r,c,v in noise)); cc=sorted(set(c for r,c,v in noise))
    O=[]
    for ri in range(len(rr)-1):
        row=[]
        for ci in range(len(cc)-1):
            vals=[g[rr[ri]][cc[ci]],g[rr[ri]][cc[ci+1]],g[rr[ri+1]][cc[ci]],g[rr[ri+1]][cc[ci+1]]]
            c=Counter(vals)
            odds=[k for k,v in c.items() if v%2==1]
            if len(odds)==0: row.append(min(c))
            elif len(odds)==1: row.append(odds[0])
            else: row.append(bg)
        O.append(row)
    return O

